return items.map(item => {
  const joinDate = new Date(item.json["Join Date"]);
  const today = new Date();

  const daysSinceJoining = Math.floor(
    (today - joinDate) / (1000 * 60 * 60 * 24)
  );

  return {
    json: {
      ...item.json,
      DaysSinceJoining: daysSinceJoining
    }
  };
});

return items.map(item => {
    const daysSinceJoining = item.json.DaysSinceJoining;
    const daysLeftInSubscription = daysSinceJoining % 30;

    return {
        name: item.json.Name,
        daysLeftInSubscription: daysLeftInSubscription
    };
});
